import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;

    static class BigNumber {
        int number;

        BigNumber(long v) {
            v %= MOD;
            if (v < 0) v += MOD;
            number = (int) v;
        }

        static int modInverse(int a, int m) {
            int g = m, r = a, x = 0, y = 1;
            while (r != 0) {
                int q = g / r;
                int temp = g % r;
                g = r;
                r = temp;
                int x1 = x - q * y;
                x = y;
                y = x1;
            }
            return x < 0 ? x + m : x;
        }

        BigNumber add(BigNumber other) {
            int res = this.number + other.number;
            if (res >= MOD) res -= MOD;
            return new BigNumber(res);
        }

        BigNumber subtract(BigNumber other) {
            int res = this.number - other.number;
            if (res < 0) res += MOD;
            return new BigNumber(res);
        }

        static long fast_mod(long x, int m) {
            return x % m;
        }

        BigNumber multiply(BigNumber other) {
            long res = fast_mod((long) this.number * other.number, MOD);
            return new BigNumber(res);
        }

        BigNumber divide(BigNumber other) {
            return this.multiply(new BigNumber(modInverse(other.number, MOD)));
        }

        BigNumber inv() {
            return new BigNumber(modInverse(this.number, MOD));
        }

        BigNumber pow(long p) {
            assert p >= 0;
            BigNumber base = this;
            BigNumber result = new BigNumber(1);
            while (p > 0) {
                if ((p & 1) == 1) {
                    result = result.multiply(base);
                }
                base = base.multiply(base);
                p >>= 1;
            }
            return result;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof BigNumber)) return false;
            BigNumber other = (BigNumber) obj;
            return this.number == other.number;
        }

        @Override
        public int hashCode() {
            return Integer.hashCode(number);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        BigNumber[][] prob = new BigNumber[N][N];

        for (int i = 0; i < N; i++) {
            String[] parts = br.readLine().trim().split("\\s+");
            for (int j = 0; j < N; j++) {
                int p = Integer.parseInt(parts[j]);
                prob[i][j] = new BigNumber(p).divide(new BigNumber(100));
            }
        }

        Map<List<Boolean>, BigNumber> stateMap = new HashMap<>();
        List<Boolean> initialMask = new ArrayList<>(Collections.nCopies(1 << N, false));
        initialMask.set(0, true);
        stateMap.put(initialMask, new BigNumber(1));

        for (int leftIdx = 0; leftIdx < N; leftIdx++) {
            Map<List<Boolean>, BigNumber> newStateMap = new HashMap<>();
            for (int maskCurr = 0; maskCurr < (1 << N); maskCurr++) {
                BigNumber product = new BigNumber(1);
                for (int rightIdx = 0; rightIdx < N; rightIdx++) {
                    boolean bitSet = ((maskCurr >> rightIdx) & 1) != 0;
                    if (bitSet) {
                        product = product.multiply(prob[leftIdx][rightIdx]);
                    } else {
                        product = product.multiply(new BigNumber(1).subtract(prob[leftIdx][rightIdx]));
                    }
                }
                for (Map.Entry<List<Boolean>, BigNumber> entry : stateMap.entrySet()) {
                    List<Boolean> possibleMask = entry.getKey();
                    BigNumber probValue = entry.getValue();
                    List<Boolean> tempMask = new ArrayList<>(Collections.nCopies(1 << N, false));
                    for (int m = 0; m < (1 << N); m++) {
                        if (possibleMask.get(m)) {
                            for (int i = 0; i < N; i++) {
                                if (((maskCurr >> i) & 1) != 0 && ((m >> i) & 1) == 0) {
                                    tempMask.set(m | (1 << i), true);
                                }
                            }
                        }
                    }
                    BigNumber prevVal = newStateMap.getOrDefault(tempMask, new BigNumber(0));
                    newStateMap.put(tempMask, prevVal.add(probValue.multiply(product)));
                }
            }
            stateMap = newStateMap;
        }

        BigNumber total = new BigNumber(0);
        for (Map.Entry<List<Boolean>, BigNumber> p : stateMap.entrySet()) {
            List<Boolean> mask = p.getKey();
            if (mask.get((1 << N) - 1)) {
                total = total.add(p.getValue());
            }
        }

        System.out.println(total.number);
    }
}
